// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport android.bluetooth.BluetoothAdapterimport android.bluetooth.BluetoothManagerimport android.content.Contextimport android.content.Intentimport android.net.wifi.WifiManagerimport android.os.Buildimport android.provider.Settingsimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Result/** * NOUS — Connectivity Services (Module 10 v2 — Step 10.5). * * Three thin service interfaces wrapping Android connectivity APIs (Wi-Fi, * Bluetooth, Airplane Mode) for handler testability. * * ## Why interfaces? * * Android's `WifiManager`, `BluetoothAdapter`, and `Settings.Global` are * concrete classes requiring a `Context`. Wrapping them behind interfaces * allows pure-Kotlin unit tests (no Robolectric) and documents exactly * which APIs the handlers depend on. * * ## API level constraints (per strategy v2 §"Privacy & Security") * *  - **Wi-Fi**: API 28- can toggle programmatically (`WifiManager.setWifiEnabled`). *    API 29+ cannot — must launch `Settings.Panel.ACTION_WIFI` for the user *    to toggle manually. [WifiService.canToggleDirectly] reports which path *    is available. * *  - **Bluetooth**: API 30- can toggle programmatically (`BluetoothAdapter.enable`). *    API 31+ cannot — must launch `Settings.ACTION_BLUETOOTH_SETTINGS`. Also requires *    `BLUETOOTH_CONNECT` permission on API 31+. * *  - **Airplane Mode**: `Settings.Global.AIRPLANE_MODE_ON` write requires *    `WRITE_SECURE_SETTINGS` — granted only to system apps, rooted devices, *    or via ADB. Regular apps fall back to opening the Settings page. */// ──────────────────────────────────────────────────────────────────────────// Wi-Fi service// ──────────────────────────────────────────────────────────────────────────/** * Wraps the subset of [WifiManager] that [WifiHandler] uses. */interface WifiService {    /** True if the device has a Wi-Fi radio. */    fun isAvailable(): Boolean    /** True if Wi-Fi is currently enabled. */    fun isEnabled(): Boolean    /**     * True if this app can toggle Wi-Fi programmatically.     *     * Returns false on API 29+ (Android restricts background toggling).     * When false, callers must use [openSettingsPanel] instead.     */    fun canToggleDirectly(): Boolean    /**     * Toggle Wi-Fi on/off. Returns true on success.     *     * Always returns false on API 29+ (use [openSettingsPanel]).     */    fun setEnabled(enabled: Boolean): Boolean    /**     * Open the Wi-Fi Settings panel (API 29+) or Wi-Fi Settings page (older).     *     * On API 29+, opens the inline `Settings.Panel.ACTION_WIFI` panel.     * On older versions, opens the full `Settings.ACTION_WIFI_SETTINGS` page.     *     * @return true if the panel/page was launched successfully.     */    fun openSettingsPanel(): Boolean}/** * Android [WifiService] backed by [WifiManager]. */class AndroidWifiService(    private val context: Context,    private val wifiManager: WifiManager?,) : WifiService {    override fun isAvailable(): Boolean = wifiManager != null    override fun isEnabled(): Boolean = try {        wifiManager?.isWifiEnabled ?: false    } catch (t: SecurityException) {        // ACCESS_WIFI_STATE not granted.        false    }    override fun canToggleDirectly(): Boolean {        // API 29+ blocks programmatic toggle for non-system apps.        return Build.VERSION.SDK_INT < Build.VERSION_CODES.Q    }    override fun setEnabled(enabled: Boolean): Boolean {        if (!canToggleDirectly()) return false        return try {            @Suppress("DEPRECATION")            wifiManager?.setWifiEnabled(enabled) ?: false        } catch (t: SecurityException) {            Timber.tag("AndroidWifiService").w("CHANGE_WIFI_STATE not granted", t)            false        } catch (t: Throwable) {            Timber.tag("AndroidWifiService").w("setWifiEnabled failed", t)            false        }    }    override fun openSettingsPanel(): Boolean = try {        val intent = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {            Intent(Settings.Panel.ACTION_WIFI)        } else {            @Suppress("DEPRECATION")            Intent(Settings.ACTION_WIFI_SETTINGS)        }.apply { addFlags(Intent.FLAG_ACTIVITY_NEW_TASK) }        context.startActivity(intent)        true    } catch (t: Throwable) {        Timber.tag("AndroidWifiService").w("Failed to open Wi-Fi settings", t)        false    }}// ──────────────────────────────────────────────────────────────────────────// Bluetooth service// ──────────────────────────────────────────────────────────────────────────/** * Wraps the subset of [BluetoothAdapter] that [BluetoothHandler] uses. */interface BluetoothService {    /** True if the device has a Bluetooth radio. */    fun isAvailable(): Boolean    /** True if Bluetooth is currently enabled. */    fun isEnabled(): Boolean    /**     * True if this app can toggle Bluetooth programmatically.     *     * Returns false on API 31+ (Android 12+) — must use [openSettingsPanel].     */    fun canToggleDirectly(): Boolean    /**     * Toggle Bluetooth on/off. Returns true on success.     *     * Always returns false on API 31+ (use [openSettingsPanel]).     */    fun setEnabled(enabled: Boolean): Boolean    /**     * Open the Bluetooth Settings panel (API 31+) or page (older).     *     * @return true if the panel/page was launched successfully.     */    fun openSettingsPanel(): Boolean}/** * Android [BluetoothService] backed by [BluetoothAdapter]. */class AndroidBluetoothService(    private val context: Context,    private val bluetoothManager: BluetoothManager?,) : BluetoothService {    private val adapter: BluetoothAdapter? get() = bluetoothManager?.adapter    override fun isAvailable(): Boolean = adapter != null    override fun isEnabled(): Boolean = try {        adapter?.isEnabled ?: false    } catch (t: SecurityException) {        false    }    override fun canToggleDirectly(): Boolean {        // API 31+ (Android 12) blocks programmatic toggle.        return Build.VERSION.SDK_INT < Build.VERSION_CODES.S    }    override fun setEnabled(enabled: Boolean): Boolean {        if (!canToggleDirectly()) return false        return try {            val result = if (enabled) adapter?.enable() else adapter?.disable()            result == true  // true = action initiated (async — actual state changes later)        } catch (t: SecurityException) {            Timber.tag("AndroidBluetoothService").w("BLUETOOTH_CONNECT not granted", t)            false        } catch (t: Throwable) {            Timber.tag("AndroidBluetoothService").w("setEnabled failed", t)            false        }    }    override fun openSettingsPanel(): Boolean = try {        val intent = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {            Intent(Settings.ACTION_BLUETOOTH_SETTINGS)        } else {            Intent(Settings.ACTION_BLUETOOTH_SETTINGS)        }.apply { addFlags(Intent.FLAG_ACTIVITY_NEW_TASK) }        context.startActivity(intent)        true    } catch (t: Throwable) {        Timber.tag("AndroidBluetoothService").w("Failed to open Bluetooth settings", t)        false    }}// ──────────────────────────────────────────────────────────────────────────// Airplane mode service// ──────────────────────────────────────────────────────────────────────────/** * Wraps the subset of `Settings.Global` for airplane mode that [AirplaneModeHandler] uses. */interface AirplaneModeService {    /** True if airplane mode is currently on. */    fun isOn(): Boolean    /**     * True if this app can toggle airplane mode programmatically.     *     * Requires `WRITE_SECURE_SETTINGS` — granted only to system apps, rooted     * devices, or via ADB. Regular apps return false.     */    fun canToggleDirectly(): Boolean    /**     * Toggle airplane mode on/off. Returns true on success.     *     * Always returns false if [canToggleDirectly] is false.     */    fun setOn(on: Boolean): Boolean    /**     * Open the Airplane Mode Settings page.     *     * @return true if the page was launched successfully.     */    fun openSettingsPage(): Boolean}/** * Android [AirplaneModeService] backed by `Settings.Global`. */class AndroidAirplaneModeService(    private val context: Context,    private val settingsHelper: com.roshan.persona.system.util.SettingsHelper,) : AirplaneModeService {    override fun isOn(): Boolean = try {        Settings.Global.getInt(            context.contentResolver,            Settings.Global.AIRPLANE_MODE_ON,            0,        ) == 1    } catch (t: Throwable) {        false    }    override fun canToggleDirectly(): Boolean = settingsHelper.canWriteSecureSettings()    override fun setOn(on: Boolean): Boolean {        if (!canToggleDirectly()) return false        return try {            Settings.Global.putInt(                context.contentResolver,                Settings.Global.AIRPLANE_MODE_ON,                if (on) 1 else 0,            )            // Broadcast the change so the system updates the radio state.            val intent = Intent(Intent.ACTION_AIRPLANE_MODE_CHANGED)                .putExtra("state", on)            context.sendBroadcast(intent)            true        } catch (t: SecurityException) {            Timber.tag("AndroidAirplaneModeService").w("WRITE_SECURE_SETTINGS not granted", t)            false        } catch (t: Throwable) {            Timber.tag("AndroidAirplaneModeService").w("setOn failed", t)            false        }    }    override fun openSettingsPage(): Boolean = try {        val intent = Intent(Settings.ACTION_AIRPLANE_MODE_SETTINGS)            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)        context.startActivity(intent)        true    } catch (t: Throwable) {        Timber.tag("AndroidAirplaneModeService").w("Failed to open airplane mode settings", t)        false    }}